#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        long long x, y;
        cin >> x >> y;
        // 答案等于 y - x 的二进制中 1 的个数
        cout << __builtin_popcountll((unsigned long long)(y - x)) << '\n';
    }
    return 0;
}
